from decimal import Decimal, getcontext, ROUND_HALF_UP, InvalidOperation

getcontext().prec = 80

_Q2 = Decimal("0.01")

# Contenido de LS_PARAMETROS cargado por 02_parametros.sql. SOLO se usa cuando
# inp["params"] no viene informado (ausente o vacio). Si params viene
# informado, se considera que ES el contenido completo de LS_PARAMETROS y un
# parametro ausente provoca ORA-20010 (fn_param_num, lineas 98-112).
_DEFAULT_PARAMS = {
    "DIAS_MAX_DENUNCIA": "30",
    "DIAS_MAX_DENUNCIA_VIDA": "365",
    "DEDUCIBLE_MINIMO": "100",
    "PCT_DESCUENTO_DED_VIP": "50",
    "TOLERANCIA_MORA_VIP": "500",
    "MAX_SINIESTROS_ANUAL": "3",
    "PCT_PENALIZACION_SINIEST": "10",
    "UMBRAL_RETENCION": "10000",
    "TASA_RETENCION": "2",
    "TOPE_AUTO_APROBACION": "50000",
    "DIAS_ALERTA_FRAUDE": "15",
    "PCT_ALERTA_FRAUDE": "80",
    "FACTOR_INFLACION": "1.035",
    "TASA_IVA": "19",
    "VERSION_MOTOR": None,
}


class _OraError(Exception):
    def __init__(self, code, message):
        Exception.__init__(self, message)
        self.code = code
        self.message = message


def _is_null_text(s):
    return s == "" or s.lower() in ("null", "none")


def _dec(value, default="0"):
    if value is None:
        return Decimal(default)
    s = str(value).strip().strip('"').strip("'").strip()
    if _is_null_text(s):
        return Decimal(default)
    try:
        return Decimal(s)
    except InvalidOperation:
        return Decimal(default)


def _dec_or_null(value):
    # Valor numerico de parametro: puede ser NULL (valor_numerico NULL).
    if value is None:
        return None
    if isinstance(value, bool):
        return Decimal(1) if value else Decimal(0)
    s = str(value).strip().strip('"').strip("'").strip()
    if _is_null_text(s):
        return None
    try:
        return Decimal(s)
    except InvalidOperation:
        return None


def _n2(value):
    # Asignacion a NUMBER(14,2) / ROUND(x,2): mitad alejandose de cero. NULL se conserva.
    if value is None:
        return None
    return Decimal(value).quantize(_Q2, rounding=ROUND_HALF_UP)


def _fmt2(value):
    d = _n2(value)
    if d == 0:
        d = Decimal("0.00")
    return format(d, "f")


# Aritmetica/comparaciones SQL con NULL
def _sub(a, b):
    return None if a is None or b is None else a - b


def _mul(a, b):
    return None if a is None or b is None else a * b


def _div(a, b):
    return None if a is None or b is None else a / b


def _gt(a, b):
    return a is not None and b is not None and a > b


def _ge(a, b):
    return a is not None and b is not None and a >= b


def _lt(a, b):
    return a is not None and b is not None and a < b


def _le(a, b):
    return a is not None and b is not None and a <= b


def _parse_bool(value):
    if isinstance(value, bool):
        return value
    s = str(value).strip().strip('"').strip("'").upper()
    return s in ("TRUE", "T", "1", "S", "SI", "Y", "YES")


def _days_from_civil(y, m, d):
    y -= 1 if m <= 2 else 0
    era = (y if y >= 0 else y - 399) // 400
    yoe = y - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _date_ord(value):
    # TRUNC(fecha): solo la parte YYYY-MM-DD.
    s = str(value).strip().strip('"').strip("'")[:10]
    parts = s.split("-")
    return _days_from_civil(int(parts[0]), int(parts[1]), int(parts[2]))


def _parse_params(raw):
    # Devuelve dict con el contenido de LS_PARAMETROS.
    if raw is None:
        return dict(_DEFAULT_PARAMS)
    if isinstance(raw, dict):
        if not raw:
            return dict(_DEFAULT_PARAMS)
        return {str(k).strip().upper(): v for k, v in raw.items()}
    s = str(raw).strip()
    if s.startswith("{"):
        s = s[1:]
    if s.endswith("}"):
        s = s[:-1]
    s = s.strip()
    if s == "":
        return dict(_DEFAULT_PARAMS)
    s = s.replace("\n", ",").replace(";", ",")
    result = {}
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        sep = None
        for cand in (":", "="):
            if cand in item:
                sep = cand
                break
        if sep is None:
            continue
        k, v = item.split(sep, 1)
        k = k.strip().strip('"').strip("'").strip().upper()
        v = v.strip().strip('"').strip("'").strip()
        if k:
            result[k] = v
    return result


def _add_obs(obs, mark):
    # PR_AGREGAR_OBS
    if obs is None or obs == "":
        return mark
    return obs + ";" + mark


def _result(status, reason, base, ded, cov, wth, net, obs):
    return {
        "status": status,
        "reason_code": reason,
        "base_amount": _fmt2(base),
        "deductible_amount": _fmt2(ded),
        "covered_amount": _fmt2(cov),
        "withholding_amount": _fmt2(wth),
        "net_amount": _fmt2(net),
        "observations": obs if obs else "",
    }


def _liquidar(inp):
    params = _parse_params(inp.get("params"))

    def p(code):
        # FN_PARAM_NUM: ORA-20010 si no existe; puede devolver NULL.
        if code not in params:
            raise _OraError("ORA-20010", "Parametro no definido: " + code)
        return _dec_or_null(params.get(code))

    claimed = _n2(_dec(inp.get("claimed_amount")))
    occ = _date_ord(inp.get("occurrence_date"))
    rep = _date_ord(inp.get("report_date"))
    pol_status = str(inp.get("policy_status", "")).strip()
    pol_start = _date_ord(inp.get("policy_start_date"))
    pol_end = _date_ord(inp.get("policy_end_date"))
    ramo = str(inp.get("line_of_business", "")).strip()
    sum_insured = _n2(_dec(inp.get("sum_insured")))
    ded_type = str(inp.get("deductible_type", "")).strip()
    ded_value = _n2(_dec(inp.get("deductible_value")))
    pending_premium = _n2(_dec(inp.get("pending_premium")))
    category = str(inp.get("customer_category", "")).strip()
    coverage_found = _parse_bool(inp.get("coverage_found", "false"))
    cov_limit = _n2(_dec(inp.get("coverage_limit")))
    cov_pct = _n2(_dec(inp.get("coverage_pct")))
    waiting_days = _dec(inp.get("waiting_days"))
    prior_count = _dec(inp.get("prior_liquidated_claims_365d"))
    total_indemnified = _dec(inp.get("total_indemnified"))

    zero = Decimal("0")

    def reject(reason, obs=None):
        # PR_RECHAZAR: importes en 0
        return _result("RECHAZADA", reason, zero, zero, zero, zero, zero, obs)

    observations = None

    # Linea 375: se lee FACTOR_INFLACION antes de cualquier validacion.
    p("FACTOR_INFLACION")

    # 1.a (linea 386)
    if pol_status != "VIGENTE":
        return reject("POLIZA_NO_VIGENTE")

    # 1.b (lineas 395-396)
    if occ < pol_start or occ > pol_end:
        return reject("FUERA_DE_VIGENCIA")

    # 1.c (lineas 407-418)
    dias_denuncia = Decimal(rep - occ)
    if ramo == "VIDA":
        dias_max = p("DIAS_MAX_DENUNCIA_VIDA")
    else:
        dias_max = p("DIAS_MAX_DENUNCIA")
    if _gt(dias_denuncia, dias_max):
        return reject("DENUNCIA_EXTEMPORANEA")

    # 1.d (lineas 423-433)
    if not coverage_found:
        return reject("COBERTURA_NO_CONTRATADA")

    # 1.e (lineas 440-445)
    dias_desde_inicio = Decimal(occ - pol_start)
    if dias_desde_inicio < waiting_days:
        return reject("EN_PERIODO_CARENCIA")

    # 1.f (lineas 451-462)
    if pending_premium > 0:
        tolerancia = p("TOLERANCIA_MORA_VIP")
        if category == "VIP" and _le(pending_premium, tolerancia):
            observations = _add_obs(observations, "TOLERANCIA_MORA_VIP")
        else:
            return reject("PRIMA_EN_MORA", observations)

    # 2.a (lineas 487-492)
    if claimed > cov_limit:
        base = _n2(cov_limit)
        observations = _add_obs(observations, "LIMITE_COBERTURA")
    else:
        base = _n2(claimed)

    # 2.b fn_calcular_deducible (lineas 179-208); v_deducible NUMBER(14,2)
    if ded_type == "FIJO":
        deductible = _n2(ded_value)
    else:
        ded_min = p("DEDUCIBLE_MINIMO")
        deductible = _n2(_div(_mul(base, ded_value), Decimal(100)))
        if _lt(deductible, ded_min):
            deductible = _n2(ded_min)
            observations = _add_obs(observations, "DEDUCIBLE_MINIMO")
    if category == "VIP" and _gt(deductible, zero):
        pct_vip = p("PCT_DESCUENTO_DED_VIP")
        deductible = _n2(_div(_mul(deductible, _sub(Decimal(100), pct_vip)), Decimal(100)))
        observations = _add_obs(observations, "DESCUENTO_VIP")

    # 2.c (lineas 503-508)
    covered = _n2(_div(_mul(_sub(base, deductible), cov_pct), Decimal(100)))
    if _le(covered, zero):
        return reject("BAJO_DEDUCIBLE", observations)

    # 2.d (lineas 521-533)
    if _ge(prior_count, p("MAX_SINIESTROS_ANUAL")):
        pct_pen = p("PCT_PENALIZACION_SINIEST")
        covered = _n2(_div(_mul(covered, _sub(Decimal(100), pct_pen)), Decimal(100)))
        observations = _add_obs(observations, "PENALIZACION_SINIESTRALIDAD")

    # 2.e (lineas 541-558)
    remanente = sum_insured - total_indemnified
    if remanente <= 0:
        return reject("SUMA_ASEGURADA_AGOTADA", observations)
    if _gt(covered, remanente):
        covered = _n2(remanente)
        observations = _add_obs(observations, "TOPE_SUMA_ASEGURADA")

    # 2.f (lineas 565-574)
    if ramo != "VIDA" and _gt(covered, p("UMBRAL_RETENCION")):
        withholding = _n2(_div(_mul(covered, p("TASA_RETENCION")), Decimal(100)))
        observations = _add_obs(observations, "RETENCION_APLICADA")
    else:
        withholding = zero
    net = _n2(_sub(covered, withholding))

    # 3. Estado final (lineas 586-599)
    umbral_fraude = _n2(_div(_mul(cov_limit, p("PCT_ALERTA_FRAUDE")), Decimal(100)))
    if _le(dias_desde_inicio, p("DIAS_ALERTA_FRAUDE")) and _ge(claimed, umbral_fraude):
        status = "PENDIENTE_APROBACION"
        reason = "SOSPECHA_FRAUDE"
    elif _gt(net, p("TOPE_AUTO_APROBACION")):
        status = "PENDIENTE_APROBACION"
        reason = "SUPERA_TOPE_AUTOMATICO"
    else:
        status = "APROBADA"
        reason = "LIQUIDACION_AUTOMATICA"

    # INSERT en columnas NOT NULL (pr_registrar_resultado): NULL => ORA-01400
    for v in (base, deductible, covered, withholding, net):
        if v is None:
            raise _OraError("ORA-01400", "No se puede insertar NULL en LS_LIQUIDACIONES")

    return _result(status, reason, base, deductible, covered, withholding, net, observations)


def run(inp: dict) -> dict:
    try:
        return _liquidar(inp)
    except _OraError as e:
        # pr_procesar_lote: WHEN OTHERS => ROLLBACK TO sp_siniestro; sin liquidacion
        return {
            "status": "ERROR",
            "reason_code": e.code,
            "base_amount": "0.00",
            "deductible_amount": "0.00",
            "covered_amount": "0.00",
            "withholding_amount": "0.00",
            "net_amount": "0.00",
            "observations": e.message,
        }
